function isFirestoreTimestamp(x) { return x && typeof x === "object" && typeof x.seconds === "number" && typeof x.nanoseconds === "number"; }
function toDateSafe(x) {
  if (!x) return null;
  if (x instanceof Date) return x;
  if (isFirestoreTimestamp(x)) return new Date(x.seconds * 1000);
  if (x && typeof x.toDate === "function") return x.toDate();
  if (typeof x === "string") { const d = new Date(x); return Number.isNaN(d.getTime()) ? null : d; }
  return null;
}
function toISODateString(d) {
  if (!(d instanceof Date)) return "";
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}
function normalizeSelectedDates(raw) {
  const arr = Array.isArray(raw) ? raw : [];
  const seen = new Set();
  return arr.map(toDateSafe).filter(Boolean).map(d => new Date(d.getFullYear(), d.getMonth(), d.getDate()))
    .filter(d => { const k = toISODateString(d); if (!k || seen.has(k)) return false; seen.add(k); return true; })
    .sort((a,b)=>a-b);
}
function sameDay(a,b){ return a instanceof Date && b instanceof Date && a.getFullYear()===b.getFullYear() && a.getMonth()===b.getMonth() && a.getDate()===b.getDate(); }
function currencyGH(amount){ const n=Number(amount||0); try{return new Intl.NumberFormat("en-GH",{style:"currency",currency:"GHS"}).format(n);}catch{return `GH₵ ${n.toFixed(2)}`;} }
function hashColor(str){ let h=0; const s=String(str||"item"); for(let i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))>>>0; return `hsl(${h%360} 70% 55%)`; }
function getQuarterLabel(d){ return `Q${Math.floor(d.getMonth()/3)+1} ${d.getFullYear()}`; }
function getMonthLabel(d){ return format(d,"MMM yyyy"); }
function safeTimeToLocaleString(x){ const d=toDateSafe(x); return d ? d.toLocaleString() : ""; }
function clampMoney(n){ const v=Number(n||0); return Number.isFinite(v) ? Math.max(0,v) : 0; }
function computeBookingTotalAmount(b){ const days=normalizeSelectedDates(b?.selectedDates).length; const computed=Number(b?.dailyRate||0)*days; if(b?.status==="cancelled") return Number(b?.penalty||0)>0?Number(b.penalty):0; if(b?.status==="confirmed") return Number(b?.confirmedAmount||0)>0?Number(b.confirmedAmount):computed; return computed; }
function computePaymentStatus(total, paid){ const t=clampMoney(total), p=clampMoney(paid); if(t<=0||p<=0) return "unpaid"; return p+0.0001<t ? "partial" : "paid"; }
function sourceTypeLabel(type){ if(type==="main") return "Main / MAALVILA"; if(type==="rental_company") return "Attached Rental Company"; if(type==="individual") return "Individual / Other"; return "Unknown"; }
function sourceBadgeClass(type){ if(type==="main") return "text-emerald-800 bg-emerald-50 border-emerald-200"; if(type==="rental_company") return "text-blue-800 bg-blue-50 border-blue-200"; if(type==="individual") return "text-violet-800 bg-violet-50 border-violet-200"; return "text-slate-700 bg-slate-50 border-slate-200"; }

const GHANA_VAT_RATE=0.15, GHANA_NHIL_RATE=0.025, GHANA_GETFUND_RATE=0.025;
