  const [carNumber,setCarNumber]=useState(""), [driver,setDriver]=useState(""), [driverPhone,setDriverPhone]=useState(""), [dailyRate,setDailyRate]=useState(""), [selectedDates,setSelectedDates]=useState([]), [editBookingId,setEditBookingId]=useState(null);
