  const revenueTrendData=useMemo(()=>{const map=new Map(); for(const b of bookings){ if(b.status!=="confirmed")continue; const amt=Number(b.confirmedAmount||0); if(!amt)continue; const dates=normalizeSelectedDates(b.selectedDates); const anchor=dates.find(d=>d>=last90Range.start&&d<=last90Range.end)||toDateSafe(b.createdAt)||dates[0]||null; if(!anchor||anchor<last90Range.start||anchor>last90Range.end)continue; const key=trendMode==="quarterly"?getQuarterLabel(anchor):getMonthLabel(anchor); map.set(key,(map.get(key)||0)+amt);} const keys=[],cur=new Date(last90Range.start),seen=new Set(); while(cur<=last90Range.end){const k=trendMode==="quarterly"?getQuarterLabel(cur):getMonthLabel(cur); if(!seen.has(k)){seen.add(k);keys.push(k);} cur.setMonth(cur.getMonth()+1);} return keys.map(k=>({period:k,revenue:Number(map.get(k)||0)}));},[bookings,trendMode,last90Range]);
